        public static double Predict(double[] features)
        {
            return (double)(float)PredictRaw(features);
        }

        public static double PredictRaw(double[] features)
        {
            if (features == null)
                throw new ArgumentNullException(nameof(features));
            if (features.Length != FeatureCount)
                throw new ArgumentException($"Expected {FeatureCount} features, got {features.Length}.", nameof(features));

            double total = 0.0;
            for (int tree = 0; tree < TreeRoots.Length; tree++)
                total += EvaluateTree(TreeRoots[tree], features);
            return total;
        }

        private static double EvaluateTree(int node, double[] features)
        {
            while (FeatureIndex[node] >= 0)
            {
                int feature = FeatureIndex[node];
                double value = features[feature];
                bool goLeft;

                if (double.IsNaN(value))
                {
                    goLeft = DefaultLeft[node] != 0;
                }
                else if (MissingType[node] == 1 && value == 0.0)
                {
                    goLeft = DefaultLeft[node] != 0;
                }
                else
                {
                    goLeft = value <= Threshold[node];
                }

                node = goLeft ? LeftChild[node] : RightChild[node];
            }

            return LeafValue[node];
        }
    }
}

namespace CTraderModel06Standalone
{
    /// <summary>
    /// Standalone C# implementation of the 48-feature Model06 contract.
    /// The formulas mirror the Python feature pipeline used by
    /// 02_conservative_0600_daily015_total075.yaml.
    /// </summary>
    public static class Model06Features
    {
        public readonly struct Bar
        {
            public Bar(DateTime time, double open, double high, double low, double close, double volume)
            {
                Time = time;
                Open = open;
                High = high;
                Low = low;
                Close = close;
                Volume = volume;
            }

            public DateTime Time { get; }
            public double Open { get; }
            public double High { get; }
            public double Low { get; }
            public double Close { get; }
            public double Volume { get; }
        }

        private const double Eps = 1e-12;
        private const double RatioEps = 1e-8;

        public static double[] ComputeLatest(IReadOnlyList<Bar> bars)
        {
            if (bars == null) throw new ArgumentNullException(nameof(bars));
            var rows = ComputeRows(bars, new[] { bars.Count - 1 });
            return rows[0];
        }

        /// <summary>
        /// Compute Model06 feature vectors for selected bar indices in a single full-history pass.
        /// Recursive indicators are evaluated once over the supplied history, then the requested
        /// rows are assembled without recomputing the pipeline for every parity timestamp.
        /// </summary>
        public static double[][] ComputeRows(IReadOnlyList<Bar> bars, IReadOnlyList<int> indices)
        {
            if (bars == null) throw new ArgumentNullException(nameof(bars));
            if (indices == null) throw new ArgumentNullException(nameof(indices));
            if (bars.Count < 400)
                throw new ArgumentException("Model06 requires at least 400 warm-up bars for a finite feature vector.", nameof(bars));
            if (indices.Count == 0)
                return Array.Empty<double[]>();

            int n = bars.Count;
            foreach (var index in indices)
                if (index < 0 || index >= n)
                    throw new ArgumentOutOfRangeException(nameof(indices), $"Requested feature index {index} is outside [0, {n - 1}].");

            var open = new double[n];
            var high = new double[n];
            var low = new double[n];
            var close = new double[n];
            var volume = new double[n];
            for (int i = 0; i < n; i++)
            {
                open[i] = bars[i].Open;
                high[i] = bars[i].High;
                low[i] = bars[i].Low;
                close[i] = bars[i].Close;
                volume[i] = bars[i].Volume;
            }

            var closeRet = SimpleReturns(close, 1, castFloat32: false);
            var vol24 = RollingStd(closeRet, 24, ddof: 1);
            var vol48 = RollingStd(closeRet, 48, ddof: 1);
            var vol96 = RollingStd(closeRet, 96, ddof: 1);
            var vol192 = RollingStd(closeRet, 192, ddof: 1);

            var ema24 = Ema(close, 24);
            var ema48 = Ema(close, 48);
            var ema96 = Ema(close, 96);
            var ema192 = Ema(close, 192);

            var tr = TrueRange(high, low, close);
            var atr48 = Wilder(tr, 48);

            var mesa = Mesa(close, 0.5, 0.05);
            var decycler = Decycler(close, 60);
            var instantaneousTrendline = InstantaneousTrendline(close, 0.07);
            var frama = Frama(close, high, low, 16, 4, 300);
            var supersmoother = SuperSmoother(close, 10);
            var roofing = RoofingFilter(close, 48, 10);

            var bb = Bollinger(close, 192, 2.0);
            var atrPct = new double[n];
            var atrOverPrice = new double[n];
            var emaTrend48192 = new double[n];
            var closeOverBbUpper = new double[n];
            var closeOverBbMid = new double[n];
            var closeOverVwap32 = new double[n];
            var vwap32 = Vwap(high, low, close, volume, 32);

            for (int i = 0; i < n; i++)
            {
                atrOverPrice[i] = RatioFloat32(atr48[i], close[i], 0.0);
                atrPct[i] = Float32(SafeDivide(atr48[i], close[i]));
                emaTrend48192[i] = RatioFloat32(ema48[i], ema192[i], 1.0);
                closeOverBbUpper[i] = RatioFloat32(close[i], bb.Upper[i], 1.0);
                closeOverBbMid[i] = RatioFloat32(close[i], bb.Mid[i], 1.0);
                closeOverVwap32[i] = RatioFloat32(close[i], vwap32[i], 1.0);
            }

            var atrPctRank192 = RollingPercentRank(atrPct, 192, inputAlreadyFloat32: true);
            var bbBandwidthRank192 = RollingPercentRank(bb.Bandwidth, 192, inputAlreadyFloat32: false);
            var robustZ128 = RobustZScore(closeRet, 128, shiftStats: true, madScale: 1.4826);

            double[] BuildRow(int k)
            {
                var result = new double[48];
                result[0] = closeRet[k];
                result[1] = Lag(closeRet, k, 1);
                result[2] = Lag(closeRet, k, 2);
                result[3] = Lag(closeRet, k, 4);
                result[4] = Lag(closeRet, k, 8);
                result[5] = Lag(closeRet, k, 16);
                result[6] = Lag(closeRet, k, 24);
                result[7] = Lag(closeRet, k, 48);

                result[8] = ReturnFloat32(close, k, 1);
                result[9] = ReturnFloat32(close, k, 4);
                result[10] = ReturnFloat32(close, k, 8);
                result[11] = ReturnFloat32(close, k, 16);
                result[12] = ReturnFloat32(close, k, 24);
                result[13] = ReturnFloat32(close, k, 48);
                result[14] = ReturnFloat32(close, k, 24);
                result[15] = ReturnFloat32(close, k, 48);

                result[16] = vol24[k];
                result[17] = vol48[k];
                result[18] = vol96[k];
                result[19] = vol192[k];
                result[20] = atr48[k];
                result[21] = atrOverPrice[k];
                result[22] = atrPct[k];
                result[23] = atrPctRank192[k];
                result[24] = emaTrend48192[k];
                result[25] = closeOverBbUpper[k];
                result[26] = closeOverBbMid[k];
                result[27] = bb.PercentB[k];
                result[28] = bb.Bandwidth[k];
                result[29] = bbBandwidthRank192[k];

                result[30] = EmaAlignmentFloat(ema24[k], ema96[k], ema192[k]);
                result[31] = Float32(SafeDivide(Math.Abs(close[k] - ema24[k]), atr48[k]));
                result[32] = Float32(SafeDivide(Math.Abs(close[k] - ema96[k]), atr48[k]));
                result[33] = Float32(SafeDivide(mesa.Mama[k] - mesa.Fama[k], atr48[k]));
                result[34] = Float32(SafeDivide(close[k] - decycler[k], atr48[k]));
                result[35] = Float32(SafeDivide(Diff(instantaneousTrendline, k, 1), atr48[k]));
                result[36] = Float32(SafeDivide(Diff(decycler, k, 1), atr48[k]));
                result[37] = Float32(SafeDivide(Diff(frama, k, 1), atr48[k]));
                result[38] = Float32(SafeDivide(Diff(supersmoother, k, 1), atr48[k]));
                result[39] = Float32(SafeDivide(roofing[k], atr48[k]));
                result[40] = Float32(Mod(mesa.Phase[k], 360.0) / 360.0);

                double range = high[k] - low[k];
                result[41] = Float32(SafeDivide(Math.Abs(close[k] - open[k]), range));
                result[42] = Float32(SafeDivide(high[k] - Math.Max(open[k], close[k]), range));
                result[43] = Float32(SafeDivide(Math.Min(open[k], close[k]) - low[k], range));
                result[44] = Float32(SafeDivide(close[k] - low[k], range));
                result[45] = Float32(SafeDivide(range, atr48[k]));
                result[46] = closeOverVwap32[k];
                result[47] = robustZ128[k];

                for (int i = 0; i < result.Length; i++)
                    if (!double.IsFinite(result[i]))
                        throw new InvalidOperationException($"Non-finite Model06 feature at bar {k}, index {i} ({Model06Predictor.FeatureOrder[i]}): {result[i]}");
                return result;
            }

            var rows = new double[indices.Count][];
            for (int i = 0; i < indices.Count; i++)
                rows[i] = BuildRow(indices[i]);
            return rows;
        }

        private static double Float32(double value) => (double)(float)value;

        private static double SafeDivide(double numerator, double denominator)
        {
            if (!double.IsFinite(numerator) || !double.IsFinite(denominator) || denominator == 0.0)
                return double.NaN;
            return numerator / denominator;
        }

        private static double RatioFloat32(double numerator, double denominator, double subtract)
        {
            if (!double.IsFinite(numerator) || !double.IsFinite(denominator) || Math.Abs(denominator) <= RatioEps)
                return double.NaN;
            return Float32(numerator / denominator - subtract);
        }

        private static double[] SimpleReturns(double[] close, int lag, bool castFloat32)
        {
            var r = FillNaN(close.Length);
            for (int i = lag; i < close.Length; i++)
            {
                if (!double.IsFinite(close[i]) || !double.IsFinite(close[i - lag]) || close[i - lag] == 0.0) continue;
                double v = close[i] / close[i - lag] - 1.0;
                r[i] = castFloat32 ? Float32(v) : v;
            }
            return r;
        }

        private static double ReturnFloat32(double[] close, int index, int lag)
        {
            if (index < lag || close[index - lag] == 0.0) return double.NaN;
            return Float32(close[index] / close[index - lag] - 1.0);
        }

        private static double Lag(double[] values, int index, int lag) => index >= lag ? values[index - lag] : double.NaN;
        private static double Diff(double[] values, int index, int lag) => index >= lag ? values[index] - values[index - lag] : double.NaN;

        private static double[] RollingStd(double[] values, int window, int ddof)
        {
            var output = FillNaN(values.Length);
            for (int i = window - 1; i < values.Length; i++)
            {
                double sum = 0.0;
                bool valid = true;
                for (int j = i - window + 1; j <= i; j++)
                {
                    if (!double.IsFinite(values[j])) { valid = false; break; }
                    sum += values[j];
                }
                if (!valid) continue;
                double mean = sum / window;
                double ss = 0.0;
                for (int j = i - window + 1; j <= i; j++)
                {
                    double d = values[j] - mean;
                    ss += d * d;
                }
                output[i] = Math.Sqrt(ss / (window - ddof));
            }
            return output;
        }

        private static double[] Ema(double[] values, int span)
        {
            var output = FillNaN(values.Length);
            double alpha = 2.0 / (span + 1.0);
            double state = double.NaN;
            for (int i = 0; i < values.Length; i++)
            {
                double x = values[i];
                if (!double.IsFinite(x)) continue;
                state = double.IsFinite(state) ? alpha * x + (1.0 - alpha) * state : x;
                output[i] = state;
            }
            return output;
        }

        private static double[] TrueRange(double[] high, double[] low, double[] close)
        {
            var output = FillNaN(close.Length);
            for (int i = 0; i < close.Length; i++)
            {
                if (!double.IsFinite(high[i]) || !double.IsFinite(low[i])) continue;
                double a = high[i] - low[i];
                if (i == 0 || !double.IsFinite(close[i - 1])) { output[i] = a; continue; }
                double b = Math.Abs(high[i] - close[i - 1]);
                double c = Math.Abs(low[i] - close[i - 1]);
                output[i] = Math.Max(a, Math.Max(b, c));
            }
            return output;
        }

        private static double[] Wilder(double[] values, int window)
        {
            var output = FillNaN(values.Length);
            var seed = new Queue<double>();
            double state = double.NaN;
            for (int i = 0; i < values.Length; i++)
            {
                double x = values[i];
                if (!double.IsFinite(x))
                {
                    seed.Clear(); state = double.NaN; continue;
                }
                if (!double.IsFinite(state))
                {
                    seed.Enqueue(x);
                    while (seed.Count > window) seed.Dequeue();
                    if (seed.Count < window) continue;
                    state = seed.Average();
                }
                else
                {
                    state = ((state * (window - 1.0)) + x) / window;
                }
                output[i] = state;
            }
            return output;
        }

        private sealed class BollingerResult
        {
            public double[] Mid = Array.Empty<double>();
            public double[] Upper = Array.Empty<double>();
            public double[] PercentB = Array.Empty<double>();
            public double[] Bandwidth = Array.Empty<double>();
        }

        private static BollingerResult Bollinger(double[] close, int window, double nStd)
        {
            var mid = FillNaN(close.Length);
            var upper = FillNaN(close.Length);
            var percentB = FillNaN(close.Length);
            var bandwidth = FillNaN(close.Length);
            for (int i = window - 1; i < close.Length; i++)
            {
                double sum = 0.0; bool valid = true;
                for (int j = i - window + 1; j <= i; j++)
                {
                    if (!double.IsFinite(close[j])) { valid = false; break; }
                    sum += close[j];
                }
                if (!valid) continue;
                double mean = sum / window;
                double ss = 0.0;
                for (int j = i - window + 1; j <= i; j++) { double d = close[j] - mean; ss += d * d; }
                double sd = Math.Sqrt(ss / window);
                double up = mean + nStd * sd;
                double lo = mean - nStd * sd;
                mid[i] = mean; upper[i] = up;
                bandwidth[i] = mean == 0.0 ? double.NaN : (up - lo) / mean;
                percentB[i] = up == lo ? double.NaN : (close[i] - lo) / (up - lo);
            }
            return new BollingerResult { Mid = mid, Upper = upper, PercentB = percentB, Bandwidth = bandwidth };
        }

        private static double[] RollingPercentRank(double[] values, int window, bool inputAlreadyFloat32)
        {
            var output = FillNaN(values.Length);
            for (int i = window - 1; i < values.Length; i++)
            {
                double current = values[i];
                if (!double.IsFinite(current)) continue;
                int valid = 0, le = 0;
                for (int j = i - window + 1; j <= i; j++)
                {
                    double x = values[j];
                    if (!double.IsFinite(x)) continue;
                    valid++;
                    if (x <= current) le++;
                }
                if (valid == window)
                    output[i] = Float32((double)le / valid);
            }
            return output;
        }

        private static double EmaAlignmentFloat(double fast, double mid, double slow)
        {
            if (fast > mid && mid > slow) return 1.0;
            if (fast < mid && mid < slow) return -1.0;
            return 0.0;
        }

        private static double[] Vwap(double[] high, double[] low, double[] close, double[] volume, int window)
        {
            var output = FillNaN(close.Length);
            for (int i = window - 1; i < close.Length; i++)
            {
                double numerator = 0.0, denominator = 0.0; bool valid = true;
                for (int j = i - window + 1; j <= i; j++)
                {
                    if (!double.IsFinite(high[j]) || !double.IsFinite(low[j]) || !double.IsFinite(close[j]) || !double.IsFinite(volume[j])) { valid = false; break; }
                    double typical = (high[j] + low[j] + close[j]) / 3.0;
                    numerator += typical * volume[j];
                    denominator += volume[j];
                }
                if (valid && denominator != 0.0) output[i] = numerator / denominator;
            }
            return output;
        }

        private static double[] RobustZScore(double[] source, int window, bool shiftStats, double madScale)
        {
            var output = FillNaN(source.Length);
            for (int i = 0; i < source.Length; i++)
            {
                int end = shiftStats ? i - 1 : i;
                int start = end - window + 1;
                if (start < 0 || end < 0 || !double.IsFinite(source[i])) continue;
                var sample = new double[window]; bool valid = true;
                for (int j = 0; j < window; j++)
                {
                    double x = source[start + j];
                    if (!double.IsFinite(x)) { valid = false; break; }
                    sample[j] = x;
                }
                if (!valid) continue;
                double median = Median(sample);
                var deviations = new double[window];
                for (int j = 0; j < window; j++) deviations[j] = Math.Abs(sample[j] - median);
                double mad = Median(deviations);
                double denom = mad * madScale;
                if (denom == 0.0) continue;
                output[i] = Float32((source[i] - median) / denom);
            }
            return output;
        }

        private static double Median(double[] values)
        {
            var copy = (double[])values.Clone();
            Array.Sort(copy);
            int n = copy.Length;
            return (n & 1) == 1 ? copy[n / 2] : (copy[n / 2 - 1] + copy[n / 2]) / 2.0;
        }

        private sealed class MesaResult
        {
            public double[] Phase = Array.Empty<double>();
            public double[] Mama = Array.Empty<double>();
            public double[] Fama = Array.Empty<double>();
        }

        private static MesaResult Mesa(double[] values, double fastLimit, double slowLimit)
        {
            int n = values.Length;
            var smooth = WeightedSmooth(values);
            var detrender = new double[n]; var q1 = new double[n]; var i1 = new double[n]; var ji = new double[n]; var jq = new double[n];
            var i2 = new double[n]; var q2 = new double[n]; var re = new double[n]; var im = new double[n];
            var phase = FillNaN(n); var mama = FillNaN(n); var fama = FillNaN(n);
            double previousPeriod = 10.0, previousSmoothPeriod = 10.0, previousPhase = 0.0;
            double previousMama = double.NaN, previousFama = double.NaN;

            for (int idx = 0; idx < n; idx++)
            {
                double price = values[idx]; if (!double.IsFinite(price)) continue;
                if (!double.IsFinite(previousMama)) { previousMama = price; previousFama = price; }
                double scale = 0.075 * previousPeriod + 0.54;
                detrender[idx] = FirHilbert(smooth, idx, scale);
                q1[idx] = FirHilbert(detrender, idx, scale);
                i1[idx] = idx >= 3 ? detrender[idx - 3] : 0.0;
                ji[idx] = FirHilbert(i1, idx, scale);
                jq[idx] = FirHilbert(q1, idx, scale);
                double rawI2 = i1[idx] - jq[idx], rawQ2 = q1[idx] + ji[idx];
                i2[idx] = 0.2 * rawI2 + 0.8 * (idx > 0 ? i2[idx - 1] : 0.0);
                q2[idx] = 0.2 * rawQ2 + 0.8 * (idx > 0 ? q2[idx - 1] : 0.0);
                double rawRe = i2[idx] * (idx > 0 ? i2[idx - 1] : 0.0) + q2[idx] * (idx > 0 ? q2[idx - 1] : 0.0);
                double rawIm = i2[idx] * (idx > 0 ? q2[idx - 1] : 0.0) - q2[idx] * (idx > 0 ? i2[idx - 1] : 0.0);
                re[idx] = 0.2 * rawRe + 0.8 * (idx > 0 ? re[idx - 1] : 0.0);
                im[idx] = 0.2 * rawIm + 0.8 * (idx > 0 ? im[idx - 1] : 0.0);

                double currentPeriod = previousPeriod;
                double angle = (Math.Abs(re[idx]) > Eps || Math.Abs(im[idx]) > Eps) ? Math.Abs(Math.Atan2(im[idx], re[idx])) : 0.0;
                if (angle > Eps)
                {
                    double rawPeriod = 2.0 * Math.PI / angle;
                    rawPeriod = Math.Min(rawPeriod, 1.5 * previousPeriod);
                    rawPeriod = Math.Max(rawPeriod, 0.67 * previousPeriod);
                    rawPeriod = Math.Min(Math.Max(rawPeriod, 6.0), 50.0);
                    currentPeriod = 0.2 * rawPeriod + 0.8 * previousPeriod;
                }
                double currentSmoothPeriod = 0.33 * currentPeriod + 0.67 * previousSmoothPeriod;
                double currentPhase = previousPhase;
                if (Math.Abs(i1[idx]) > Eps || Math.Abs(q1[idx]) > Eps)
                {
                    currentPhase = Math.Atan2(q1[idx], i1[idx]) * 180.0 / Math.PI;
                    if (currentPhase < 0.0) currentPhase += 360.0;
                }
                double currentDeltaPhase = previousPhase - currentPhase;
                if (previousPhase < 90.0 && currentPhase > 270.0) currentDeltaPhase = previousPhase + 360.0 - currentPhase;
                if (currentDeltaPhase < 1.0) currentDeltaPhase = 1.0;
                double currentAlpha = Math.Min(fastLimit, Math.Max(slowLimit, fastLimit / currentDeltaPhase));
                double currentMama = currentAlpha * price + (1.0 - currentAlpha) * previousMama;
                double currentFama = 0.5 * currentAlpha * currentMama + (1.0 - 0.5 * currentAlpha) * previousFama;
                phase[idx] = currentPhase; mama[idx] = currentMama; fama[idx] = currentFama;
                previousPeriod = currentPeriod; previousSmoothPeriod = currentSmoothPeriod; previousPhase = currentPhase;
                previousMama = currentMama; previousFama = currentFama;
            }
            return new MesaResult { Phase = phase, Mama = mama, Fama = fama };
        }

        private static double[] WeightedSmooth(double[] values)
        {
            var smooth = FillNaN(values.Length);
            for (int i = 0; i < values.Length; i++)
            {
                if (i < 3) { if (double.IsFinite(values[i])) smooth[i] = values[i]; continue; }
                if (AllFinite(values, i - 3, 4)) smooth[i] = (4.0 * values[i] + 3.0 * values[i - 1] + 2.0 * values[i - 2] + values[i - 3]) / 10.0;
            }
            return smooth;
        }

        private static double FirHilbert(double[] values, int idx, double scale)
        {
            if (idx < 6) return 0.0;
            if (!double.IsFinite(values[idx]) || !double.IsFinite(values[idx - 2]) || !double.IsFinite(values[idx - 4]) || !double.IsFinite(values[idx - 6])) return 0.0;
            return (0.0962 * values[idx] + 0.5769 * values[idx - 2] - 0.5769 * values[idx - 4] - 0.0962 * values[idx - 6]) * scale;
        }

        private static double[] HighPass(double[] values, int period)
        {
            var output = FillNaN(values.Length); var state = new double[values.Length];
            double angle = 0.707 * 2.0 * Math.PI / period;
            double alpha = (Math.Cos(angle) + Math.Sin(angle) - 1.0) / Math.Cos(angle);
            for (int i = 0; i < values.Length; i++)
            {
                if (!double.IsFinite(values[i])) continue;
                if (i < 2) { state[i] = 0.0; output[i] = 0.0; continue; }
                if (!AllFinite(values, i - 2, 3)) continue;
                state[i] = Math.Pow(1.0 - alpha / 2.0, 2.0) * (values[i] - 2.0 * values[i - 1] + values[i - 2])
                    + 2.0 * (1.0 - alpha) * state[i - 1] - Math.Pow(1.0 - alpha, 2.0) * state[i - 2];
                output[i] = state[i];
            }
            return output;
        }

        private static double[] Decycler(double[] values, int period)
        {
            var hp = HighPass(values, period); var output = FillNaN(values.Length);
            for (int i = 0; i < values.Length; i++) if (double.IsFinite(values[i]) && double.IsFinite(hp[i])) output[i] = values[i] - hp[i];
            return output;
        }

        private static double[] InstantaneousTrendline(double[] values, double a)
        {
            var t = FillNaN(values.Length);
            for (int i = 0; i < values.Length; i++)
            {
                if (!double.IsFinite(values[i])) continue;
                if (i < 2) t[i] = values[i];
                else if (i < 7)
                {
                    if (AllFinite(values, i - 2, 3)) t[i] = (values[i] + 2.0 * values[i - 1] + values[i - 2]) / 4.0;
                }
                else if (AllFinite(values, i - 2, 3) && double.IsFinite(t[i - 1]) && double.IsFinite(t[i - 2]))
                {
                    t[i] = (a - a * a / 4.0) * values[i] + 0.5 * a * a * values[i - 1] - (a - 0.75 * a * a) * values[i - 2]
                         + 2.0 * (1.0 - a) * t[i - 1] - Math.Pow(1.0 - a, 2.0) * t[i - 2];
                }
            }
            return t;
        }

        private static double[] Frama(double[] price, double[] high, double[] low, int window, int fastPeriod, int slowPeriod)
        {
            var output = FillNaN(price.Length); int half = window / 2;
            double fastAlpha = 2.0 / (fastPeriod + 1.0), slowAlpha = 2.0 / (slowPeriod + 1.0), previous = double.NaN;
            for (int i = 0; i < price.Length; i++)
            {
                if (!double.IsFinite(price[i])) continue;
                if (!double.IsFinite(previous)) previous = price[i];
                if (i + 1 < window) { output[i] = price[i]; previous = output[i]; continue; }
                int start = i - window + 1;
                if (!AllFinite(high, start, window) || !AllFinite(low, start, window)) continue;
                double n1 = (Max(high, start, half) - Min(low, start, half)) / half;
                double n2 = (Max(high, start + half, half) - Min(low, start + half, half)) / half;
                double n3 = (Max(high, start, window) - Min(low, start, window)) / window;
                double dimension = (n1 > Eps && n2 > Eps && n3 > Eps) ? (Math.Log(n1 + n2) - Math.Log(n3)) / Math.Log(2.0) : 1.0;
                double alpha = Math.Exp(-4.6 * (dimension - 1.0));
                alpha = Math.Min(fastAlpha, Math.Max(slowAlpha, alpha));
                double current = alpha * price[i] + (1.0 - alpha) * previous;
                output[i] = current; previous = current;
            }
            return output;
        }

        private static double[] SuperSmoother(double[] values, int period)
        {
            var result = FillNaN(values.Length); if (values.Length == 0) return result;
            double a1 = Math.Exp(-Math.Sqrt(2.0) * Math.PI / period);
            double b1 = 2.0 * a1 * Math.Cos(Math.Sqrt(2.0) * Math.PI / period);
            double c2 = b1, c3 = -(a1 * a1), c1 = 1.0 - c2 - c3;
            var state = new double[values.Length];
            if (double.IsFinite(values[0])) { state[0] = values[0]; result[0] = state[0]; }
            if (values.Length > 1 && double.IsFinite(values[0]) && double.IsFinite(values[1])) { state[1] = (values[0] + values[1]) / 2.0; result[1] = state[1]; }
            for (int i = 2; i < values.Length; i++)
            {
                if (!double.IsFinite(values[i - 1]) || !double.IsFinite(values[i])) continue;
                state[i] = c1 * (values[i] + values[i - 1]) / 2.0 + c2 * state[i - 1] + c3 * state[i - 2]; result[i] = state[i];
            }
            return result;
        }

        private static double[] RoofingFilter(double[] values, int hpPeriod, int lpPeriod)
        {
            var filt = FillNaN(values.Length); var hp = new double[values.Length]; var state = new double[values.Length];
            double angleHp = 0.707 * 2.0 * Math.PI / hpPeriod;
            double alpha = (Math.Cos(angleHp) + Math.Sin(angleHp) - 1.0) / Math.Cos(angleHp);
            double a1 = Math.Exp(-Math.Sqrt(2.0) * Math.PI / lpPeriod);
            double b1 = 2.0 * a1 * Math.Cos(Math.Sqrt(2.0) * Math.PI / lpPeriod);
            double c2 = b1, c3 = -(a1 * a1), c1 = 1.0 - c2 - c3;
            for (int i = 2; i < values.Length; i++)
            {
                if (!AllFinite(values, i - 2, 3)) continue;
                hp[i] = Math.Pow(1.0 - alpha / 2.0, 2.0) * (values[i] - 2.0 * values[i - 1] + values[i - 2])
                    + 2.0 * (1.0 - alpha) * hp[i - 1] - Math.Pow(1.0 - alpha, 2.0) * hp[i - 2];
                state[i] = c1 * (hp[i] + hp[i - 1]) / 2.0 + c2 * state[i - 1] + c3 * state[i - 2];
                filt[i] = state[i];
            }
            return filt;
        }

        private static double Mod(double x, double m) => ((x % m) + m) % m;
        private static double[] FillNaN(int n) { var a = new double[n]; for (int i = 0; i < n; i++) a[i] = double.NaN; return a; }
        private static bool AllFinite(double[] a, int start, int count) { for (int i = start; i < start + count; i++) if (!double.IsFinite(a[i])) return false; return true; }
        private static double Min(double[] a, int start, int count) { double v = double.PositiveInfinity; for (int i = start; i < start + count; i++) v = Math.Min(v, a[i]); return v; }
        private static double Max(double[] a, int start, int count) { double v = double.NegativeInfinity; for (int i = start; i < start + count; i++) v = Math.Max(v, a[i]); return v; }
    }
}

namespace CTraderModel06Standalone
{
    /// <summary>
    /// Incremental/stateful implementation of the exact 48-feature Model06 contract.
    /// Each bar is processed once. Rolling windows scan at most 192 observations;
    /// recursive EMA/Ehlers/ATR state is carried forward instead of being reseeded.
    /// </summary>
    public sealed class Model06StreamingFeatures
    {
        private const double Eps = 1e-12;
        private const double RatioEps = 1e-8;

        private readonly List<double> _open = new();
        private readonly List<double> _high = new();
        private readonly List<double> _low = new();
        private readonly List<double> _close = new();
        private readonly List<double> _volume = new();
        private readonly List<double> _closeRet = new();

        private readonly List<double> _ema24 = new();
        private readonly List<double> _ema48 = new();
        private readonly List<double> _ema96 = new();
        private readonly List<double> _ema192 = new();

        private readonly List<double> _tr = new();
        private readonly List<double> _atr48 = new();
        private readonly Queue<double> _atrSeed = new();
        private double _atrState = double.NaN;
        private readonly List<double> _atrPct = new();

        private readonly List<double> _bbBandwidth = new();

        // MESA / MAMA / FAMA state.
        private readonly List<double> _mesaSmooth = new();
        private readonly List<double> _mesaDetrender = new();
        private readonly List<double> _mesaQ1 = new();
        private readonly List<double> _mesaI1 = new();
        private readonly List<double> _mesaJi = new();
        private readonly List<double> _mesaJq = new();
        private readonly List<double> _mesaI2 = new();
        private readonly List<double> _mesaQ2 = new();
        private readonly List<double> _mesaRe = new();
        private readonly List<double> _mesaIm = new();
        private readonly List<double> _mesaPhase = new();
        private readonly List<double> _mesaMama = new();
        private readonly List<double> _mesaFama = new();
        private double _mesaPreviousPeriod = 10.0;
        private double _mesaPreviousSmoothPeriod = 10.0;
        private double _mesaPreviousPhase = 0.0;
        private double _mesaPreviousMama = double.NaN;
        private double _mesaPreviousFama = double.NaN;

        // Ehlers recursive filters.
        private readonly List<double> _decyclerHp = new();
        private readonly List<double> _decycler = new();
        private readonly List<double> _instantaneousTrendline = new();
        private double _framaPrevious = double.NaN;
        private readonly List<double> _frama = new();
        private readonly List<double> _superState = new();
        private readonly List<double> _supersmoother = new();
        private readonly List<double> _roofHp = new();
        private readonly List<double> _roofState = new();
        private readonly List<double> _roofing = new();

        public int Count => _close.Count;
        public DateTime? LastTime { get; private set; }
        public double[] LatestFeatures { get; private set; }

        /// <summary>
        /// Append one strictly newer bar. Returns true when all 48 Model06 features are finite.
        /// </summary>
        public bool TryAdd(Model06Features.Bar bar, out double[] features)
        {
            if (LastTime.HasValue && bar.Time <= LastTime.Value)
                throw new ArgumentException($"Bars must be strictly increasing. Last={LastTime:O}, new={bar.Time:O}.", nameof(bar));

            LastTime = bar.Time;
            int k = _close.Count;
            _open.Add(bar.Open);
            _high.Add(bar.High);
            _low.Add(bar.Low);
            _close.Add(bar.Close);
            _volume.Add(bar.Volume);

            double closeRet = k == 0 || _close[k - 1] == 0.0
                ? double.NaN
                : bar.Close / _close[k - 1] - 1.0;
            _closeRet.Add(closeRet);

            AppendEma(_ema24, bar.Close, 24);
            AppendEma(_ema48, bar.Close, 48);
            AppendEma(_ema96, bar.Close, 96);
            AppendEma(_ema192, bar.Close, 192);

            double tr = TrueRangeAt(k);
            _tr.Add(tr);
            AppendAtr(tr);
            double atr = _atr48[k];
            double atrPct = Float32(SafeDivide(atr, bar.Close));
            _atrPct.Add(atrPct);

            var bb = BollingerAt(k, 192, 2.0);
            _bbBandwidth.Add(bb.Bandwidth);

            AppendMesa(k, bar.Close);
            AppendDecycler(k, bar.Close, 60);
            AppendInstantaneousTrendline(k, bar.Close, 0.07);
            AppendFrama(k, bar.Close, 16, 4, 300);
            AppendSuperSmoother(k, bar.Close, 10);
            AppendRoofing(k, bar.Close, 48, 10);

            var row = BuildRow(k, bb);
            for (int i = 0; i < row.Length; i++)
            {
                if (!double.IsFinite(row[i]))
                {
                    features = Array.Empty<double>();
                    LatestFeatures = null;
                    return false;
                }
            }

            LatestFeatures = row;
            features = row;
            return true;
        }

        private double[] BuildRow(int k, BollingerPoint bb)
        {
            var result = new double[48];
            result[0] = _closeRet[k];
            result[1] = Lag(_closeRet, k, 1);
            result[2] = Lag(_closeRet, k, 2);
            result[3] = Lag(_closeRet, k, 4);
            result[4] = Lag(_closeRet, k, 8);
            result[5] = Lag(_closeRet, k, 16);
            result[6] = Lag(_closeRet, k, 24);
            result[7] = Lag(_closeRet, k, 48);

            result[8] = ReturnFloat32(k, 1);
            result[9] = ReturnFloat32(k, 4);
            result[10] = ReturnFloat32(k, 8);
            result[11] = ReturnFloat32(k, 16);
            result[12] = ReturnFloat32(k, 24);
            result[13] = ReturnFloat32(k, 48);
            result[14] = ReturnFloat32(k, 24);
            result[15] = ReturnFloat32(k, 48);

            result[16] = RollingStdAt(_closeRet, k, 24, 1);
            result[17] = RollingStdAt(_closeRet, k, 48, 1);
            result[18] = RollingStdAt(_closeRet, k, 96, 1);
            result[19] = RollingStdAt(_closeRet, k, 192, 1);

            double atr = _atr48[k];
            result[20] = atr;
            result[21] = RatioFloat32(atr, _close[k], 0.0);
            result[22] = _atrPct[k];
            result[23] = RollingPercentRankAt(_atrPct, k, 192);
            result[24] = RatioFloat32(_ema48[k], _ema192[k], 1.0);
            result[25] = RatioFloat32(_close[k], bb.Upper, 1.0);
            result[26] = RatioFloat32(_close[k], bb.Mid, 1.0);
            result[27] = bb.PercentB;
            result[28] = bb.Bandwidth;
            result[29] = RollingPercentRankAt(_bbBandwidth, k, 192);

            result[30] = EmaAlignment(_ema24[k], _ema96[k], _ema192[k]);
            result[31] = Float32(SafeDivide(Math.Abs(_close[k] - _ema24[k]), atr));
            result[32] = Float32(SafeDivide(Math.Abs(_close[k] - _ema96[k]), atr));
            result[33] = Float32(SafeDivide(_mesaMama[k] - _mesaFama[k], atr));
            result[34] = Float32(SafeDivide(_close[k] - _decycler[k], atr));
            result[35] = Float32(SafeDivide(Diff(_instantaneousTrendline, k, 1), atr));
            result[36] = Float32(SafeDivide(Diff(_decycler, k, 1), atr));
            result[37] = Float32(SafeDivide(Diff(_frama, k, 1), atr));
            result[38] = Float32(SafeDivide(Diff(_supersmoother, k, 1), atr));
            result[39] = Float32(SafeDivide(_roofing[k], atr));
            result[40] = Float32(Mod(_mesaPhase[k], 360.0) / 360.0);

            double range = _high[k] - _low[k];
            result[41] = Float32(SafeDivide(Math.Abs(_close[k] - _open[k]), range));
            result[42] = Float32(SafeDivide(_high[k] - Math.Max(_open[k], _close[k]), range));
            result[43] = Float32(SafeDivide(Math.Min(_open[k], _close[k]) - _low[k], range));
            result[44] = Float32(SafeDivide(_close[k] - _low[k], range));
            result[45] = Float32(SafeDivide(range, atr));
            result[46] = RatioFloat32(_close[k], VwapAt(k, 32), 1.0);
            result[47] = RobustZAt(k, 128, 1.4826);
            return result;
        }

        private void AppendEma(List<double> output, double value, int span)
        {
            double alpha = 2.0 / (span + 1.0);
            double previous = output.Count == 0 ? double.NaN : output[^1];
            output.Add(double.IsFinite(previous) ? alpha * value + (1.0 - alpha) * previous : value);
        }

        private double TrueRangeAt(int k)
        {
            double a = _high[k] - _low[k];
            if (k == 0 || !double.IsFinite(_close[k - 1])) return a;
            double b = Math.Abs(_high[k] - _close[k - 1]);
            double c = Math.Abs(_low[k] - _close[k - 1]);
            return Math.Max(a, Math.Max(b, c));
        }

        private void AppendAtr(double tr)
        {
            if (!double.IsFinite(tr))
            {
                _atrSeed.Clear();
                _atrState = double.NaN;
                _atr48.Add(double.NaN);
                return;
            }

            if (!double.IsFinite(_atrState))
            {
                _atrSeed.Enqueue(tr);
                while (_atrSeed.Count > 48) _atrSeed.Dequeue();
                if (_atrSeed.Count < 48)
                {
                    _atr48.Add(double.NaN);
                    return;
                }
                double sum = 0.0;
                foreach (var value in _atrSeed) sum += value;
                _atrState = sum / 48.0;
            }
            else
            {
                _atrState = ((_atrState * 47.0) + tr) / 48.0;
            }
            _atr48.Add(_atrState);
        }

        private readonly struct BollingerPoint
        {
            public BollingerPoint(double mid, double upper, double percentB, double bandwidth)
            {
                Mid = mid;
                Upper = upper;
                PercentB = percentB;
                Bandwidth = bandwidth;
            }
            public double Mid { get; }
            public double Upper { get; }
            public double PercentB { get; }
            public double Bandwidth { get; }
        }

        private BollingerPoint BollingerAt(int k, int window, double nStd)
        {
            if (k + 1 < window) return new BollingerPoint(double.NaN, double.NaN, double.NaN, double.NaN);
            int start = k - window + 1;
            double sum = 0.0;
            for (int i = start; i <= k; i++)
            {
                if (!double.IsFinite(_close[i])) return new BollingerPoint(double.NaN, double.NaN, double.NaN, double.NaN);
                sum += _close[i];
            }
            double mean = sum / window;
            double ss = 0.0;
            for (int i = start; i <= k; i++)
            {
                double d = _close[i] - mean;
                ss += d * d;
            }
            double sd = Math.Sqrt(ss / window);
            double upper = mean + nStd * sd;
            double lower = mean - nStd * sd;
            double bandwidth = mean == 0.0 ? double.NaN : (upper - lower) / mean;
            double percentB = upper == lower ? double.NaN : (_close[k] - lower) / (upper - lower);
            return new BollingerPoint(mean, upper, percentB, bandwidth);
        }

        private void AppendMesa(int k, double price)
        {
            double smooth;
            if (k < 3)
                smooth = price;
            else
                smooth = (4.0 * _close[k] + 3.0 * _close[k - 1] + 2.0 * _close[k - 2] + _close[k - 3]) / 10.0;
            _mesaSmooth.Add(smooth);

            if (double.IsNaN(_mesaPreviousMama))
            {
                _mesaPreviousMama = price;
                _mesaPreviousFama = price;
            }

            double scale = 0.075 * _mesaPreviousPeriod + 0.54;
            double detrender = FirHilbert(_mesaSmooth, k, scale);
            _mesaDetrender.Add(detrender);
            double q1 = FirHilbert(_mesaDetrender, k, scale);
            _mesaQ1.Add(q1);
            double i1 = k >= 3 ? _mesaDetrender[k - 3] : 0.0;
            _mesaI1.Add(i1);
            double ji = FirHilbert(_mesaI1, k, scale);
            _mesaJi.Add(ji);
            double jq = FirHilbert(_mesaQ1, k, scale);
            _mesaJq.Add(jq);

            double rawI2 = i1 - jq;
            double rawQ2 = q1 + ji;
            double i2 = 0.2 * rawI2 + 0.8 * (k > 0 ? _mesaI2[k - 1] : 0.0);
            double q2 = 0.2 * rawQ2 + 0.8 * (k > 0 ? _mesaQ2[k - 1] : 0.0);
            _mesaI2.Add(i2);
            _mesaQ2.Add(q2);

            double rawRe = i2 * (k > 0 ? _mesaI2[k - 1] : 0.0) + q2 * (k > 0 ? _mesaQ2[k - 1] : 0.0);
            double rawIm = i2 * (k > 0 ? _mesaQ2[k - 1] : 0.0) - q2 * (k > 0 ? _mesaI2[k - 1] : 0.0);
            double re = 0.2 * rawRe + 0.8 * (k > 0 ? _mesaRe[k - 1] : 0.0);
            double im = 0.2 * rawIm + 0.8 * (k > 0 ? _mesaIm[k - 1] : 0.0);
            _mesaRe.Add(re);
            _mesaIm.Add(im);

            double currentPeriod = _mesaPreviousPeriod;
            double angle = (Math.Abs(re) > Eps || Math.Abs(im) > Eps) ? Math.Abs(Math.Atan2(im, re)) : 0.0;
            if (angle > Eps)
            {
                double rawPeriod = 2.0 * Math.PI / angle;
                rawPeriod = Math.Min(rawPeriod, 1.5 * _mesaPreviousPeriod);
                rawPeriod = Math.Max(rawPeriod, 0.67 * _mesaPreviousPeriod);
                rawPeriod = Math.Min(Math.Max(rawPeriod, 6.0), 50.0);
                currentPeriod = 0.2 * rawPeriod + 0.8 * _mesaPreviousPeriod;
            }

            double currentSmoothPeriod = 0.33 * currentPeriod + 0.67 * _mesaPreviousSmoothPeriod;
            double currentPhase = _mesaPreviousPhase;
            if (Math.Abs(i1) > Eps || Math.Abs(q1) > Eps)
            {
                currentPhase = Math.Atan2(q1, i1) * 180.0 / Math.PI;
                if (currentPhase < 0.0) currentPhase += 360.0;
            }

            double currentDeltaPhase = _mesaPreviousPhase - currentPhase;
            if (_mesaPreviousPhase < 90.0 && currentPhase > 270.0)
                currentDeltaPhase = _mesaPreviousPhase + 360.0 - currentPhase;
            if (currentDeltaPhase < 1.0) currentDeltaPhase = 1.0;

            double currentAlpha = Math.Min(0.5, Math.Max(0.05, 0.5 / currentDeltaPhase));
            double currentMama = currentAlpha * price + (1.0 - currentAlpha) * _mesaPreviousMama;
            double currentFama = 0.5 * currentAlpha * currentMama + (1.0 - 0.5 * currentAlpha) * _mesaPreviousFama;

            _mesaPhase.Add(currentPhase);
            _mesaMama.Add(currentMama);
            _mesaFama.Add(currentFama);
            _mesaPreviousPeriod = currentPeriod;
            _mesaPreviousSmoothPeriod = currentSmoothPeriod;
            _mesaPreviousPhase = currentPhase;
            _mesaPreviousMama = currentMama;
            _mesaPreviousFama = currentFama;
        }

        private static double FirHilbert(IReadOnlyList<double> values, int k, double scale)
        {
            if (k < 6) return 0.0;
            double a = values[k], b = values[k - 2], c = values[k - 4], d = values[k - 6];
            if (!double.IsFinite(a) || !double.IsFinite(b) || !double.IsFinite(c) || !double.IsFinite(d)) return 0.0;
            return (0.0962 * a + 0.5769 * b - 0.5769 * c - 0.0962 * d) * scale;
        }

        private void AppendDecycler(int k, double price, int period)
        {
            double hp;
            if (k < 2)
            {
                hp = 0.0;
            }
            else
            {
                double angle = 0.707 * 2.0 * Math.PI / period;
                double alpha = (Math.Cos(angle) + Math.Sin(angle) - 1.0) / Math.Cos(angle);
                hp = Math.Pow(1.0 - alpha / 2.0, 2.0) * (_close[k] - 2.0 * _close[k - 1] + _close[k - 2])
                    + 2.0 * (1.0 - alpha) * _decyclerHp[k - 1]
                    - Math.Pow(1.0 - alpha, 2.0) * _decyclerHp[k - 2];
            }
            _decyclerHp.Add(hp);
            _decycler.Add(price - hp);
        }

        private void AppendInstantaneousTrendline(int k, double price, double a)
        {
            double value;
            if (k < 2)
                value = price;
            else if (k < 7)
                value = (_close[k] + 2.0 * _close[k - 1] + _close[k - 2]) / 4.0;
            else
                value = (a - a * a / 4.0) * _close[k]
                    + 0.5 * a * a * _close[k - 1]
                    - (a - 0.75 * a * a) * _close[k - 2]
                    + 2.0 * (1.0 - a) * _instantaneousTrendline[k - 1]
                    - Math.Pow(1.0 - a, 2.0) * _instantaneousTrendline[k - 2];
            _instantaneousTrendline.Add(value);
        }

        private void AppendFrama(int k, double price, int window, int fastPeriod, int slowPeriod)
        {
            if (!double.IsFinite(_framaPrevious)) _framaPrevious = price;
            if (k + 1 < window)
            {
                _frama.Add(price);
                _framaPrevious = price;
                return;
            }

            int start = k - window + 1;
            int half = window / 2;
            double n1 = (Max(_high, start, half) - Min(_low, start, half)) / half;
            double n2 = (Max(_high, start + half, half) - Min(_low, start + half, half)) / half;
            double n3 = (Max(_high, start, window) - Min(_low, start, window)) / window;
            double dimension = (n1 > Eps && n2 > Eps && n3 > Eps)
                ? (Math.Log(n1 + n2) - Math.Log(n3)) / Math.Log(2.0)
                : 1.0;
            double alpha = Math.Exp(-4.6 * (dimension - 1.0));
            double fastAlpha = 2.0 / (fastPeriod + 1.0);
            double slowAlpha = 2.0 / (slowPeriod + 1.0);
            alpha = Math.Min(fastAlpha, Math.Max(slowAlpha, alpha));
            double current = alpha * price + (1.0 - alpha) * _framaPrevious;
            _frama.Add(current);
            _framaPrevious = current;
        }

        private void AppendSuperSmoother(int k, double price, int period)
        {
            double state;
            if (k == 0)
            {
                state = price;
            }
            else if (k == 1)
            {
                state = (_close[0] + _close[1]) / 2.0;
            }
            else
            {
                double a1 = Math.Exp(-Math.Sqrt(2.0) * Math.PI / period);
                double b1 = 2.0 * a1 * Math.Cos(Math.Sqrt(2.0) * Math.PI / period);
                double c2 = b1;
                double c3 = -(a1 * a1);
                double c1 = 1.0 - c2 - c3;
                state = c1 * (_close[k] + _close[k - 1]) / 2.0 + c2 * _superState[k - 1] + c3 * _superState[k - 2];
            }
            _superState.Add(state);
            _supersmoother.Add(state);
        }

        private void AppendRoofing(int k, double price, int hpPeriod, int lpPeriod)
        {
            if (k < 2)
            {
                _roofHp.Add(0.0);
                _roofState.Add(0.0);
                _roofing.Add(double.NaN);
                return;
            }

            double angleHp = 0.707 * 2.0 * Math.PI / hpPeriod;
            double alpha = (Math.Cos(angleHp) + Math.Sin(angleHp) - 1.0) / Math.Cos(angleHp);
            double hp = Math.Pow(1.0 - alpha / 2.0, 2.0) * (_close[k] - 2.0 * _close[k - 1] + _close[k - 2])
                + 2.0 * (1.0 - alpha) * _roofHp[k - 1]
                - Math.Pow(1.0 - alpha, 2.0) * _roofHp[k - 2];
            _roofHp.Add(hp);

            double a1 = Math.Exp(-Math.Sqrt(2.0) * Math.PI / lpPeriod);
            double b1 = 2.0 * a1 * Math.Cos(Math.Sqrt(2.0) * Math.PI / lpPeriod);
            double c2 = b1;
            double c3 = -(a1 * a1);
            double c1 = 1.0 - c2 - c3;
            double state = c1 * (hp + _roofHp[k - 1]) / 2.0 + c2 * _roofState[k - 1] + c3 * _roofState[k - 2];
            _roofState.Add(state);
            _roofing.Add(state);
        }

        private double ReturnFloat32(int k, int lag)
        {
            if (k < lag || _close[k - lag] == 0.0) return double.NaN;
            return Float32(_close[k] / _close[k - lag] - 1.0);
        }

        private static double RollingStdAt(IReadOnlyList<double> values, int k, int window, int ddof)
        {
            if (k + 1 < window) return double.NaN;
            int start = k - window + 1;
            double sum = 0.0;
            for (int i = start; i <= k; i++)
            {
                if (!double.IsFinite(values[i])) return double.NaN;
                sum += values[i];
            }
            double mean = sum / window;
            double ss = 0.0;
            for (int i = start; i <= k; i++)
            {
                double d = values[i] - mean;
                ss += d * d;
            }
            return Math.Sqrt(ss / (window - ddof));
        }

        private static double RollingPercentRankAt(IReadOnlyList<double> values, int k, int window)
        {
            if (k + 1 < window) return double.NaN;
            double current = values[k];
            if (!double.IsFinite(current)) return double.NaN;
            int start = k - window + 1;
            int valid = 0, le = 0;
            for (int i = start; i <= k; i++)
            {
                double value = values[i];
                if (!double.IsFinite(value)) continue;
                valid++;
                if (value <= current) le++;
            }
            return valid == window ? Float32((double)le / valid) : double.NaN;
        }

        private double VwapAt(int k, int window)
        {
            if (k + 1 < window) return double.NaN;
            int start = k - window + 1;
            double numerator = 0.0, denominator = 0.0;
            for (int i = start; i <= k; i++)
            {
                double typical = (_high[i] + _low[i] + _close[i]) / 3.0;
                numerator += typical * _volume[i];
                denominator += _volume[i];
            }
            return denominator == 0.0 ? double.NaN : numerator / denominator;
        }

        private double RobustZAt(int k, int window, double madScale)
        {
            int end = k - 1;
            int start = end - window + 1;
            if (start < 0 || !double.IsFinite(_closeRet[k])) return double.NaN;
            var sample = new double[window];
            for (int i = 0; i < window; i++)
            {
                double value = _closeRet[start + i];
                if (!double.IsFinite(value)) return double.NaN;
                sample[i] = value;
            }
            double median = Median(sample);
            var deviations = new double[window];
            for (int i = 0; i < window; i++) deviations[i] = Math.Abs(sample[i] - median);
            double mad = Median(deviations);
            double denom = mad * madScale;
            return denom == 0.0 ? double.NaN : Float32((_closeRet[k] - median) / denom);
        }

        private static double Median(double[] values)
        {
            var copy = (double[])values.Clone();
            Array.Sort(copy);
            int n = copy.Length;
            return (n & 1) == 1 ? copy[n / 2] : (copy[n / 2 - 1] + copy[n / 2]) / 2.0;
        }

        private static double EmaAlignment(double fast, double mid, double slow)
        {
            if (fast > mid && mid > slow) return 1.0;
            if (fast < mid && mid < slow) return -1.0;
            return 0.0;
        }

        private static double Lag(IReadOnlyList<double> values, int k, int lag) => k >= lag ? values[k - lag] : double.NaN;
        private static double Diff(IReadOnlyList<double> values, int k, int lag) => k >= lag ? values[k] - values[k - lag] : double.NaN;
        private static double Float32(double value) => (double)(float)value;

        private static double SafeDivide(double numerator, double denominator)
        {
            if (!double.IsFinite(numerator) || !double.IsFinite(denominator) || denominator == 0.0) return double.NaN;
            return numerator / denominator;
        }

        private static double RatioFloat32(double numerator, double denominator, double subtract)
        {
            if (!double.IsFinite(numerator) || !double.IsFinite(denominator) || Math.Abs(denominator) <= RatioEps) return double.NaN;
            return Float32(numerator / denominator - subtract);
        }

        private static double Min(IReadOnlyList<double> values, int start, int count)
        {
            double result = double.PositiveInfinity;
            for (int i = start; i < start + count; i++) result = Math.Min(result, values[i]);
            return result;
        }

        private static double Max(IReadOnlyList<double> values, int start, int count)
        {
            double result = double.NegativeInfinity;
            for (int i = start; i < start + count; i++) result = Math.Max(result, values[i]);
            return result;
        }

        private static double Mod(double x, double m) => ((x % m) + m) % m;
    }
}

namespace cAlgo.Robots
{
    /// <summary>
    /// Standalone ETHUSD M30 Model06 cBot.
    ///
    /// No Python, HTTP, LightGBM runtime, or external model file is required.
    /// The embedded predictor contains the 800 fitted LightGBM trees and the
    /// streaming feature engine carries the recursive feature state bar-by-bar.
    /// </summary>
    [Robot(TimeZone = TimeZones.UTC, AccessRights = AccessRights.None)]
    public class Model06StandaloneBacktestBot : Robot
    {
        private const string Label = "Model06Standalone";
        private const double UpperThreshold = 0.70;
        private const double LowerThreshold = -0.85;

        [Parameter("Feature history start (UTC)", DefaultValue = "2020-01-01")]
        public string FeatureHistoryStart { get; set; }

        [Parameter("Target exposure", DefaultValue = 0.60, MinValue = 0.01, MaxValue = 1.0)]
        public double TargetExposure { get; set; }

        [Parameter("Minimum holding bars", DefaultValue = 24, MinValue = 1)]
        public int MinimumHoldingBars { get; set; }

        [Parameter("Research DD guard", DefaultValue = true)]
        public bool EnableDrawdownGuard { get; set; }

        [Parameter("DD trigger", DefaultValue = 0.075, MinValue = 0.001, MaxValue = 0.50)]
        public double DrawdownTrigger { get; set; }

        [Parameter("DD cooloff bars", DefaultValue = 48, MinValue = 0, MaxValue = 10000)]
        public int DrawdownCooloffBars { get; set; }

        [Parameter("DD rearm", DefaultValue = 0.055, MinValue = 0.001, MaxValue = 0.50)]
        public double DrawdownRearm { get; set; }

        [Parameter("Maximum spread (pips)", DefaultValue = 80.0, MinValue = 0.0)]
        public double MaximumSpreadPips { get; set; }

        [Parameter("Enable orders", DefaultValue = true)]
        public bool EnableOrders { get; set; }

        [Parameter("Verbose log", DefaultValue = false)]
        public bool VerboseLog { get; set; }

        private Model06StreamingFeatures _features;
        private DateTime? _lastFedBarTime;
        private DateTime _historyStartUtc;

        // Minimum-holding state is intentionally independent from actual broker
        // positions. Research applies holding to desired positions before the DD
        // guard; a risk flatten therefore must not reset the model holding clock.
        private bool _holdingInitialized;
        private int _heldSignal;
        private int _barsSinceDesiredSwitch;

        // Research-style drawdown guard state.
        private double _peakEquity;
        private bool _guardArmed;
        private int _cooloffRemaining;
        private int _guardTriggerCount;

        protected override void OnStart()
        {
            if (!string.Equals(SymbolName, "ETHUSD", StringComparison.OrdinalIgnoreCase))
                Print("WARNING: Model06 research symbol is ETHUSD; current={0}", SymbolName);
            if (!string.Equals(TimeFrame.ToString(), "Minute30", StringComparison.OrdinalIgnoreCase))
                Print("WARNING: Model06 research timeframe is M30; current={0}", TimeFrame);

            if (!DateTime.TryParse(
                    FeatureHistoryStart,
                    CultureInfo.InvariantCulture,
                    DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal,
                    out _historyStartUtc))
            {
                throw new ArgumentException("Feature history start must be a valid UTC date, e.g. 2020-01-01.");
            }

            if (DrawdownRearm > DrawdownTrigger)
                throw new ArgumentException("DD rearm must be <= DD trigger.");

            LoadFeatureHistory();

            _features = new Model06StreamingFeatures();
            _lastFedBarTime = null;
            _holdingInitialized = false;
            _heldSignal = 0;
            _barsSinceDesiredSwitch = MinimumHoldingBars;
            _peakEquity = Account.Equity;
            _guardArmed = true;
            _cooloffRemaining = 0;
            _guardTriggerCount = 0;

            Print(
                "Model06 standalone started. trees={0}, features={1}, bars_loaded={2}, first_bar={3:O}, history_start={4:O}",
                Model06Predictor.TreeCount,
                Model06Predictor.FeatureCount,
                Bars.Count,
                Bars.Count > 0 ? Bars.OpenTimes[0] : DateTime.MinValue,
                _historyStartUtc);
        }

        protected override void OnBarClosed()
        {
            try
            {
                if (Bars.Count == 0)
                    return;

                int latestClosedIndex = Bars.Count - 1;
                DateTime latestClosedTime = Bars.OpenTimes[latestClosedIndex].ToUniversalTime();

                double[] latestFeatures = FeedThrough(latestClosedIndex, latestClosedTime);
                if (latestFeatures == null)
                    return;

                double prediction = Model06Predictor.Predict(latestFeatures);
                bool filtersPassed = FiltersPassed(latestFeatures);
                int rawSignal = SignalFrom(prediction, filtersPassed);
                int desiredSignal = ApplyMinimumHolding(rawSignal);

                bool riskGuardActive = UpdateDrawdownGuard(advanceBar: true);
                int executableSignal = riskGuardActive ? 0 : desiredSignal;

                if (VerboseLog || rawSignal != 0 || executableSignal != CurrentBrokerSignal())
                {
                    Print(
                        "bar={0:O} pred={1:F9} raw={2} held={3} exec={4} filters={5} hold={6} dd={7:P3} cooloff={8}",
                        latestClosedTime,
                        prediction,
                        rawSignal,
                        desiredSignal,
                        executableSignal,
                        filtersPassed,
                        _barsSinceDesiredSwitch,
                        CurrentDrawdown(),
                        _cooloffRemaining);
                }

                ReconcileBrokerPosition(executableSignal);

                // cTrader may apply spread/commission immediately on execution.
                // Re-evaluate after the trade so a newly crossed DD threshold is
                // flattened on the same bar as closely as broker accounting allows.
                if (EnableDrawdownGuard && UpdateDrawdownGuard(advanceBar: false) && CurrentBrokerSignal() != 0)
                    CloseStrategyPositions("dd_guard_after_execution");
            }
            catch (Exception ex)
            {
                Print("Model06 standalone fail-closed: {0}: {1}", ex.GetType().Name, ex.Message);
                CloseStrategyPositions("exception_fail_closed");
            }
        }

        private void LoadFeatureHistory()
        {
            int calls = 0;
            int totalLoaded = 0;

            while (Bars.Count == 0 || Bars.OpenTimes[0].ToUniversalTime() > _historyStartUtc)
            {
                int loaded = Bars.LoadMoreHistory();
                calls++;
                if (loaded <= 0)
                    break;
                totalLoaded += loaded;

                // Defensive bound against a broker/API anomaly.
                if (calls >= 1000)
                    break;
            }

            if (Bars.Count == 0)
                throw new InvalidOperationException("No M30 bars are available for Model06 feature initialization.");

            DateTime first = Bars.OpenTimes[0].ToUniversalTime();
            if (first > _historyStartUtc)
            {
                Print(
                    "WARNING: requested feature history starts {0:O}, but earliest available bar is {1:O}. Recursive feature state will begin there.",
                    _historyStartUtc,
                    first);
            }

            Print("Feature history load calls={0}, added={1}, bars={2}", calls, totalLoaded, Bars.Count);
        }

        private double[] FeedThrough(int latestClosedIndex, DateTime latestClosedTime)
        {
            double[] latest = null;

            for (int i = 0; i <= latestClosedIndex; i++)
            {
                DateTime time = Bars.OpenTimes[i].ToUniversalTime();
                if (time < _historyStartUtc)
                    continue;
                if (_lastFedBarTime.HasValue && time <= _lastFedBarTime.Value)
                    continue;

                bool ready = _features.TryAdd(
                    new Model06Features.Bar(
                        time,
                        Bars.OpenPrices[i],
                        Bars.HighPrices[i],
                        Bars.LowPrices[i],
                        Bars.ClosePrices[i],
                        Bars.TickVolumes[i]),
                    out var row);

                _lastFedBarTime = time;
                if (ready && time == latestClosedTime)
                    latest = row;
            }

            return latest;
        }

        private static bool FiltersPassed(double[] features)
        {
            return
                features[23] >= 0.25 &&
                features[23] <= 0.85 &&
                features[45] >= 0.8999999999999999 &&
                features[29] >= 0.40;
        }

        private static int SignalFrom(double prediction, bool filtersPassed)
        {
            if (!filtersPassed) return 0;
            if (prediction >= UpperThreshold) return 1;
            if (prediction <= LowerThreshold) return -1;
            return 0;
        }

        private int ApplyMinimumHolding(int proposedSignal)
        {
            if (!_holdingInitialized)
            {
                _holdingInitialized = true;
                _heldSignal = proposedSignal;
                _barsSinceDesiredSwitch = _heldSignal == 0 ? MinimumHoldingBars : 1;
                return _heldSignal;
            }

            bool switching = proposedSignal != _heldSignal;
            if (switching && _barsSinceDesiredSwitch < MinimumHoldingBars)
            {
                _barsSinceDesiredSwitch++;
                return _heldSignal;
            }

            if (switching)
            {
                _heldSignal = proposedSignal;
                _barsSinceDesiredSwitch = 1;
            }
            else
            {
                _barsSinceDesiredSwitch++;
            }

            return _heldSignal;
        }

        private bool UpdateDrawdownGuard(bool advanceBar)
        {
            if (_peakEquity <= 0.0 || Account.Equity > _peakEquity)
                _peakEquity = Account.Equity;

            if (!EnableDrawdownGuard)
                return false;

            double drawdown = CurrentDrawdown();
            if (!_guardArmed && drawdown <= DrawdownRearm)
                _guardArmed = true;

            bool breach =
                _guardArmed &&
                DrawdownCooloffBars > 0 &&
                drawdown >= DrawdownTrigger;

            if (breach)
            {
                _guardArmed = false;
                _cooloffRemaining = Math.Max(_cooloffRemaining, DrawdownCooloffBars);
                _guardTriggerCount++;
                if (VerboseLog)
                    Print("DD GUARD trigger #{0}: dd={1:P3}, cooloff={2}", _guardTriggerCount, drawdown, _cooloffRemaining);
            }

            bool active = breach || _cooloffRemaining > 0;
            if (advanceBar && active && _cooloffRemaining > 0)
                _cooloffRemaining--;

            return active;
        }

        private double CurrentDrawdown()
        {
            if (_peakEquity <= 0.0) return 0.0;
            return Math.Max(0.0, (_peakEquity - Account.Equity) / _peakEquity);
        }

        private int CurrentBrokerSignal()
        {
            var positions = Positions.FindAll(Label, SymbolName);
            if (positions.Length == 0) return 0;
            return positions[0].TradeType == TradeType.Buy ? 1 : -1;
        }

        private void ReconcileBrokerPosition(int targetSignal)
        {
            int currentSignal = CurrentBrokerSignal();
            if (currentSignal == targetSignal)
                return;

            if (currentSignal != 0)
                CloseStrategyPositions("target_change");

            if (targetSignal == 0 || !EnableOrders)
                return;

            double spreadPips = Symbol.PipSize > 0.0 ? Symbol.Spread / Symbol.PipSize : 0.0;
            if (spreadPips > MaximumSpreadPips)
            {
                if (VerboseLog)
                    Print("Spread blocked entry: {0:F3} > {1:F3} pips", spreadPips, MaximumSpreadPips);
                return;
            }

            double volume = CalculateTargetVolume();
            if (volume < Symbol.VolumeInUnitsMin)
            {
                Print("Target volume below symbol minimum: {0}", volume);
                return;
            }

            var type = targetSignal > 0 ? TradeType.Buy : TradeType.Sell;
            var result = ExecuteMarketOrder(type, SymbolName, volume, Label);
            if (!result.IsSuccessful)
                Print("Order failed: {0}", result.Error);
            else if (VerboseLog)
                Print("Opened {0}, units={1}, id={2}", type, volume, result.Position.Id);
        }

        private double CalculateTargetVolume()
        {
            double mid = (Symbol.Bid + Symbol.Ask) / 2.0;
            if (mid <= 0.0) return 0.0;
            double rawUnits = Account.Equity * TargetExposure / mid;
            double normalized = Symbol.NormalizeVolumeInUnits(rawUnits, RoundingMode.Down);
            return Math.Min(normalized, Symbol.VolumeInUnitsMax);
        }

        private void CloseStrategyPositions(string reason)
        {
            foreach (var position in Positions.FindAll(Label, SymbolName))
            {
                var result = ClosePosition(position);
                if (VerboseLog || !result.IsSuccessful)
                    Print("Close reason={0}, id={1}, success={2}", reason, position.Id, result.IsSuccessful);
            }
        }
    }
}
